window.VO = [{"id":"n01","text":"You can save the last doctor on Earth, or the last engineer. Not both.","at":0.24,"t0":0.12,"t1":4.25},{"id":"n02","text":"Your parents have been asking you this for years, and now you've got five seconds.","at":9.74,"t0":4.87,"t1":9.15},{"id":"n03","text":"Doctor, or engineer?","at":18.7,"t0":9.35,"t1":10.655},{"id":"m01","text":"Amma! Open his!","at":21.87,"t0":10.935,"t1":12.27},{"id":"r01","text":"Amma! Not me! Open hers!","at":24.94,"t0":12.47,"t1":14.19},{"id":"n04a","text":"Stop.","at":29.82,"t0":14.91,"t1":15.56},{"id":"n04b","text":"That isn't their mother they're shouting for.","at":32.12,"t0":16.06,"t1":18.075},{"id":"n04c","text":"It's you.","at":36.91,"t0":18.455,"t1":19.135},{"id":"n05","text":"You're the ship they're drowning in, and the last thousand people alive call you Amma.","at":39.11,"t0":19.555,"t1":23.905},{"id":"n07","text":"Ten seconds as their mother, and you're still picking by their degree.","at":48.45,"t0":24.225,"t1":27.685},{"id":"n06","text":"You've got power for one door, no time for another, and everyone watching this gets a vote.","at":56.21,"t0":28.105,"t1":32.86},{"id":"n10","text":"Open hers, and the only man who can run you drowns, and a fifteen-year-old has forty days to learn how, or you all sink.","at":66.36,"t0":33.18,"t1":40.38},{"id":"n08","text":"But Meera and Ravi are married, and you gave the bride away yourself.","at":81.36,"t0":40.68,"t1":44.375},{"id":"n09","text":"And she's carrying the only baby since the world ended.","at":90.75,"t0":45.375,"t1":48.34},{"id":"n11","text":"Open his, and you're safe, with no doctor, no baby, and he spends the rest of his life fixing you.","at":97.68,"t0":48.84,"t1":54.455},{"id":"n12","text":"Amma. Meera, or Ravi?","at":110.11,"t0":55.055,"t1":56.69}];
